import itertools

# --- Configuration ---
N = 5  # Grid size N x N
COLORS = 4 # Testing sufficiency with 4 colors

def get_neighbors_toroidal(x, y, N):
    """Returns all 8 neighboring points (and the point itself) on an N x N toroidal grid."""
    neighbors = []
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            if dx == 0 and dy == 0:
                continue # Skip the point itself

            nx = (x + dx) % N
            ny = (y + dy) % N
            neighbors.append((nx, ny))
    return neighbors

def is_coloring_valid(grid, N):
    """Checks if the current grid coloring is valid (no adjacent points have the same color)."""
    for x in range(N):
        for y in range(N):
            color = grid[x][y]
            for nx, ny in get_neighbors_toroidal(x, y, N):
                if grid[nx][ny] == color:
                    return False
    return True

def check_k4_clique(N):
    """Checks if a K4 (4 mutually adjacent points) exists, proving chi >= 4."""
    # We check a small section since the torus wrap-around doesn't help form a K4 
    # on a 5x5 grid if the coordinates are close together.

    # A 2x2 block (e.g., (0,0), (0,1), (1,0), (1,1)) is always a K4.
    points = [(0, 0), (0, 1), (1, 0), (1, 1)]

    for p1, p2 in itertools.combinations(points, 2):
        x1, y1 = p1
        x2, y2 = p2
        # Check if they are neighbors (King's move condition)
        if abs(x1 - x2) > 1 or abs(y1 - y2) > 1:
            print(f"Error: {p1} and {p2} are not neighbors.")
            return False

    print("Verification: A K4 clique exists at {(0, 0), (0, 1), (1, 0), (1, 1)}. Thus, chi >= 4.")
    return True

def greedy_color_and_check(N, k):
    """Attempts to color the N x N grid using at most k colors using a simple greedy approach."""
    # Initialize grid with -1 (uncolored)
    grid = [[-1] * N for _ in range(N)]

    # Iterate through points in order (x, y)
    for x in range(N):
        for y in range(N):
            # Determine colors used by neighbors already colored
            used_colors = set()
            for nx, ny in get_neighbors_toroidal(x, y, N):
                # Only check neighbors that have already been assigned a color (i.e., processed before (x,y))
                # Due to the iterative nature of the simple greedy algorithm, we only check neighbors (nx, ny) 
                # where (nx, ny) comes lexicographically before (x, y).
                if nx < x or (nx == x and ny < y):
                    if grid[nx][ny] != -1:
                        used_colors.add(grid[nx][ny])

            # Assign the smallest available color (0 to k-1)
            assigned_color = -1
            for color in range(k):
                if color not in used_colors:
                    assigned_color = color
                    break

            if assigned_color == -1:
                # Failed to color this point with k colors
                return False, grid

