            color_xy = color_func(x, y)

            # Check all 8 neighbors
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue

                    nx = (x + dx) % N
                    ny = (y + dy) % N

                    color_nxny = color_func(nx, ny)

                    # Constraint: Neighbors must have different colors
                    if color_xy == color_nxny:
                        print(f"Failure found at ({x}, {y}) and neighbor ({nx}, {ny}). Colors are both {color_xy}.")
                        return False
    return True

# Proposed coloring function: C(x, y) = (x + 2y) mod 4
